      # Outcome status of the most recent delivery
      field :last_status, "last_status"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
      # Timestamp updated automatically on every save
      field :modified, "modified", cast: :time
    end

    # The WebhookSubscriptionCreateRequest object.
    class WebhookSubscriptionCreateRequest
      # Whether the subscription is snapshot or event based
      field :kind, "kind"
      # Resource type for snapshot subscriptions
      field :resource, "resource"
      # Event names the subscription listens for
      field :event_types, "event_types"
      # Filters that scope which resources are delivered
      field :resource_filters, "resource_filters"
      # Destination URL where webhook payloads are sent
      field :url, "url"
      # Extra HTTP headers sent with each webhook request
      field :custom_headers, "custom_headers"
      # Hours between snapshot deliveries
      field :interval_hours, "interval_hours"
      # Maximum number of items per delivery
      field :max_items, "max_items"
      # Type of signing secret to attach to the subscription
      field :secret_type, "secret_type"
    end

    # A subscription just created, with the signing secret attached. The secret is shown
    # on this response only and never again.
    class WebhookSubscriptionCreated
      # Encoded identifier of the webhook subscription
      field :id, "id"
      # Type of webhook this subscription delivers
      field :kind, "kind"
      # Resource type the subscription is for (content or creator)
      field :resource, "resource"
      # Event types the subscription listens for
      field :event_types, "event_types"
      # Filters applied to select which resources are delivered
      field :resource_filters, "resource_filters"
      # Destination URL where webhook payloads are sent
      field :url, "url"
      # Custom HTTP headers to include with each delivery
      field :custom_headers, "custom_headers"
      # Hours between snapshot deliveries
      field :interval_hours, "interval_hours"
      # Max rows a real snapshot delivers
      field :max_items, "max_items"
      # Public prefix of the subscription signing secret
      field :secret_prefix, "secret_prefix"
      # Full signing secret, returned only once, at the moment it is minted
      field :secret, "secret"
      # Whether this subscription is active and will be dispatched
      field :enabled, "enabled"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
    end

  end
end
